$(document).ready(function () {

    var image = new Image();
image.src = "https://cdn.awsli.com.br/600x450/1736/1736356/produto/166736993/bone-vamos-defumar-o-mundo-c93b9372.jpg";
// get file name - you might need to modify this if your image url doesn't contain a file extension otherwise you can set the file name manually
var fileName = image.src.split(/(\\|\/)/g).pop();
image.onload = function () {
    var canvas = document.createElement('canvas');
    canvas.width = this.naturalWidth; // or 'width' if you want a special/scaled size
  console.log(canvas.width)
    canvas.height = this.naturalHeight; // or 'height' if you want a special/scaled size
    console.log(canvas.height)
      console.log('canvas')
    console.log(canvas)
    canvas.getContext('2d').drawImage(this, 0, 0);
    var blob;
    // ... get as Data URI

  blob = canvas.toDataURL("image/jpeg").replace("image/jpg", "image/octet-stream");
    //blob = canvas.toDataURL("image/jpeg");
   
    $("body").html("<b>Click image to download.</b><br><a download='" + fileName + "' href='" + blob + "'><img src='" + blob + "'/></a>");
};

  })

